<?php $assessment=json_decode($result['metadata'],true);$criterionTasks=wf_assessment_tasks($result); ?>
<section class="acceptance-assessment"><h2>Acceptance checks</h2>
<?php if(empty($assessment['acceptance_checks'])): ?><p>No structured acceptance checks were recorded for this result.</p><?php endif ?>
<?php foreach($assessment['acceptance_checks']??[] as $check): $criterionTask=$criterionTasks[$check['task_id']]??null;$criterion=$criterionTask?(wf_criteria($criterionTask)[$check['criterion_id']]??null):null; ?>
<article class="task-brief acceptance-card"><div class="row-top"><span class="fine"><?=e($criterionTask['title']??'Historical task')?></span><span class="status"><?=e($check['status']==='met'?'Met':'Not met')?></span></div><h3><?=e($criterion??'Criterion text is no longer publicly available')?></h3>
<p><?=e($check['reason'])?></p><details><summary>Supporting evidence<?php if($check['correction_response']??''): ?> &amp; correction response<?php endif ?></summary><blockquote><?=e($check['evidence_quote'])?></blockquote><?php if($check['correction_response']??''): ?><p><strong>Correction response:</strong> <?=e($check['correction_response'])?></p><?php endif ?><p><a href="<?=e($base)?>/tasks/<?=e($check['task_id'])?>">View task</a><?php if($check['result_id']!=='self'): ?> · <a href="<?=e($base)?>/results/<?=e($check['result_id'])?>">Evidence result</a><?php endif ?></p></details></article>
<?php endforeach ?>
<?php if($assessment['corrections']??[]): ?><h2>Targeted corrections</h2><?php foreach($assessment['corrections'] as $issue): $criterionTask=$criterionTasks[$issue['task_id']]??null; ?><article class="notice"><strong><?=e(wf_correction_label($criterionTask,$issue['criterion_id']))?></strong><p><a href="<?=e($base)?>/tasks/<?=e($issue['task_id'])?>"><?=e($criterionTask['title']??'Correct this task')?></a></p><p><?=e($issue['reason'])?></p><p><strong>Required change:</strong> <?=e($issue['required_change'])?></p></article><?php endforeach; endif ?></section>
